var LumuUI=(()=>{function a(){if(!document.body.classList.contains("page-home"))return()=>{};if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return()=>{};let t=Array.from(document.querySelectorAll("main > section"));if(!t.length)return()=>{};t.forEach((e,r)=>{e.classList.add("scroll-reveal"),e.style.transitionDelay=`${Math.min(r*45,220)}ms`});let n=new IntersectionObserver(e=>{e.forEach(r=>{r.isIntersecting&&(r.target.classList.add("is-visible"),n.unobserve(r.target))})},{threshold:.14,rootMargin:"0px 0px -8% 0px"});return t.forEach(e=>n.observe(e)),()=>{n.disconnect(),t.forEach(e=>{e.classList.remove("scroll-reveal","is-visible"),e.style.removeProperty("transition-delay")})}}function s(){try{if(window.__LUMU_UI_CLEANUP__)try{window.__LUMU_UI_CLEANUP__()}catch{}let o=[];o.push(a()),window.__LUMU_UI_CLEANUP__=()=>{o.forEach(t=>{try{t()}catch{}})}}catch{}}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",s):s();})();
